interface PaymentGateway { void charge(double amount); }

class OrderService {
    private final PaymentGateway paymentGateway; // final - niezmienne po utworzeniu
    OrderService(PaymentGateway paymentGateway) {
        this.paymentGateway = paymentGateway;
    }
    void placeOrder(double amount) { paymentGateway.charge(amount); }
}

// w main() - MY decydujemy, ktora implementacje wstrzyknac:
OrderService s1 = new OrderService(new CreditCardGateway());
OrderService s2 = new OrderService(new PayPalGateway());

TA SAMA klasa OrderService, DWIE rozne implementacje - BEZ zadnej zmiany w kodzie OrderService.

class FakePaymentGateway implements PaymentGateway {
    int callCount = 0;
    public void charge(double amount) { callCount++; }
}

FakePaymentGateway fake = new FakePaymentGateway();
OrderService testable = new OrderService(fake); // wstrzykujemy FALSZYWKE
testable.placeOrder(999.99);
// fake.callCount == 1 - zweryfikowano BEZ ani jednego polaczenia z prawdziwa bramka platnicza

Dzieki constructor injection, klasa pod testem jest testowana W IZOLACJI, bez efektow ubocznych.
